mapper.select:
SELECT id, question_type, title, difficulty, answer, analysis, create_time, update_time, creator_id, remarks FROM question
AND question_type = #{questionType}
AND title LIKE CONCAT('%', #{title}, '%')

SELECT q.id AS question_id, q.question_type, q.title, q.difficulty, q.answer, q.analysis, q.create_time, q.update_time, q.creator_id, q.remarks, qo.id AS option_id, qo.question_id AS option_question_id, qo.option_label, qo.option_content, qo.is_correct, kp.kp_name, qi.id AS image_id, qi.question_id AS image_question_id, qi.image_path, qi.type AS image_type FROM question q LEFT JOIN question_option qo ON q.id = qo.question_id LEFT JOIN question_knowledge qk ON q.id = qk.question_id LEFT JOIN knowledge_point kp ON qk.kp_id = kp.id LEFT JOIN question_image qi ON q.id = qi.question_id WHERE q.id IN
#{id}
ORDER BY q.id, qo.id, kp.kp_name, qi.id

SELECT q.id AS question_id, qo.id AS option_id, qo.question_id AS option_question_id, qo.option_label, qo.option_content, qo.is_correct, kp.kp_name, qi.id AS image_id, qi.question_id AS image_question_id, qi.image_path, qi.type AS image_type FROM question q LEFT JOIN question_option qo ON q.id = qo.question_id LEFT JOIN question_knowledge qk ON q.id = qk.question_id LEFT JOIN knowledge_point kp ON qk.kp_id = kp.id LEFT JOIN question_image qi ON q.id = qi.question_id WHERE q.id IN
#{id}
ORDER BY q.id, qo.id, kp.kp_name, qi.id

SELECT q.id AS question_id, q.question_type, q.title, q.difficulty, q.answer, q.analysis, q.create_time, q.update_time, q.creator_id, q.score, q.remarks,
qo.id AS option_id, qo.option_label, qo.option_content, qo.is_correct,
kp.kp_name
FROM question q LEFT JOIN question_option qo ON q.id = qo.question_id LEFT JOIN question_knowledge qk ON q.id = qk.question_id LEFT JOIN knowledge_point kp ON qk.kp_id = kp.id
WHERE kp.kp_name = #{kpName} AND q.question_type = #{questionType}
ORDER BY q.id, qo.option_label LIMIT #{limit}

mapper.update:
update question
question_type = #{questionType}, title = #{title}, difficulty = #{difficulty}, answer = #{answer}, analysis = #{analysis}, create_time = #{createTime}, update_time = #{updateTime}, creator_id = #{creatorId}, remarks = #{remarks},
where id = #{id}
